<?php
/**
 * Plugin Name: Kickgent GitHub Sync
 * Description: Imports reviewed Kickgent pages generated from the canonical Next.js main branch.
 * Version: 1.0.0
 */
defined('ABSPATH')||exit;
function kg_sync_base(){return apply_filters('kg_sync_base','https://raw.githubusercontent.com/omarreact/mt4-grey-label-kickgent-next/main/wordpress/kickgent-fse/data/');}
function kg_sync_json($file){$r=wp_safe_remote_get(kg_sync_base().$file,['timeout'=>20]);if(is_wp_error($r))return $r;if(200!==wp_remote_retrieve_response_code($r))return new WP_Error('kg_http','GitHub feed is unavailable.');$body=wp_remote_retrieve_body($r);$json=json_decode($body,true);return is_array($json)?[$json,$body]:new WP_Error('kg_json','GitHub feed is invalid.');}
function kg_sync_state(){$m=kg_sync_json('manifest.json');if(is_wp_error($m))return $m;[$manifest]=$m;$f=kg_sync_json($manifest['feed']);if(is_wp_error($f))return $f;[$feed,$body]=$f;$sha=sha1('blob '.strlen($body)."\0".$body);if(!hash_equals((string)$manifest['feedGitBlobSha'],$sha))return new WP_Error('kg_checksum','GitHub feed checksum mismatch.');return [$manifest,$feed];}
function kg_sync_import(){$state=kg_sync_state();if(is_wp_error($state))return $state;[$m,$feed]=$state;$home=0;$count=0;foreach($feed['pages'] as $page){$slug=sanitize_title($page['slug']??'');if(!$slug)continue;$old=get_page_by_path($slug,OBJECT,'page');$post=['post_type'=>'page','post_status'=>'publish','post_title'=>sanitize_text_field($page['title']??$slug),'post_name'=>$slug,'post_content'=>"<!-- wp:html -->\n".($page['content']??'')."\n<!-- /wp:html -->"];if($old)$post['ID']=$old->ID;$id=wp_insert_post(wp_slash($post),true);if(is_wp_error($id))return $id;update_post_meta($id,'_kickgent_source_commit',$m['sourceCommit']);if($slug==='home')$home=$id;$count++;}if($home){update_option('show_on_front','page');update_option('page_on_front',$home);}update_option('kg_sync_version',$m['sourceCommit'],false);wp_cache_flush();return [$count,$m['sourceCommit']];}
function kg_sync_admin(){if(!current_user_can('manage_options'))return;$note='';if(isset($_POST['kg_sync_import'])){check_admin_referer('kg_sync_import');$r=kg_sync_import();$note=is_wp_error($r)?$r->get_error_message():sprintf('Imported %d pages from GitHub commit %s.',$r[0],$r[1]);}$state=kg_sync_state();echo '<div class="wrap"><h1>Kickgent GitHub Sync</h1>';if($note)echo '<div class="notice"><p>'.esc_html($note).'</p></div>';echo '<p><strong>Installed:</strong> '.esc_html(get_option('kg_sync_version','Not imported yet')).'</p>';if(!is_wp_error($state))echo '<p><strong>Available:</strong> '.esc_html($state[0]['sourceCommit']).' · '.intval($state[0]['pageCount']).' pages</p>';else echo '<p>'.esc_html($state->get_error_message()).'</p>';echo '<p>Review GitHub first. The next import replaces direct WordPress edits to synced pages.</p><form method="post">';wp_nonce_field('kg_sync_import');submit_button('Import latest reviewed GitHub version','primary','kg_sync_import',false);echo '</form></div>';}
add_action('admin_menu',fn()=>add_management_page('Kickgent GitHub Sync','Kickgent GitHub Sync','manage_options','kickgent-github-sync','kg_sync_admin'));
